function updateRequestCount(level, countSelector, empuser) {
    frappe.call({
        method: `sahayog_asset.sahayog_asset.doctype.asset_request.asset_request.get_level_${level}_count`,
        args: {
            employee_user: empuser
        },
        callback: function(response) {
            var RequestCount = response.message;
            console.log(`Level ${level} Request:`, RequestCount);

            var levelElement = root_element.querySelector(countSelector);
            levelElement.textContent = RequestCount;

            // Hide the level if count is zero
            if (RequestCount === 0) {
                levelElement.closest('.widget').style.display = 'none';
            }
        },
        error: function(err) {
            console.error(`Error fetching Level ${level} count:`, err);
        }
    });
}

